  interface Props {
    /** 后端 platform 字段（pornhub / xhamster / beeg …） */
    platform: string;
    /** 平台显示名，只用于 alt / title / 读屏，不显示成文字 */
    label: string;
    class?: string;
  }

  let { platform, label, class: className = '' }: Props = $props();

  /* 位图标记是从平台自家 app icon 里抠出来的单色剪影（白色 + alpha），
     不用 filter 就能与这里的白字黑底配色对齐；都是几 KB，Vite 直接内联成 data URI。 */
  const MARKS: Record<string, string> = {
    pornhub: pornhubMark,
    xhamster: xhamsterMark,
  };

  let key = $derived(platform.toLowerCase());
  let mark = $derived(MARKS[key]);
</script>

